//===- bolt/Passes/PLTCall.h - PLT call optimization --===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
//===--===//
//
// This file implements the PLTCall class, which replaces calls to PLT entries
// with indirect calls against GOT.
//
//===--===//
#include "bolt/Passes/PLTCall.h"
#include "llvm/Support/CommandLine.h"
#define DEBUG_TYPE "bolt-plt"
using namespace llvm;
namespace opts {
extern cl::OptionCategory BoltOptCategory;
static cl::opt<bolt::PLTCall::OptType>
PLT("plt",
cl::desc("optimize PLT calls (requires linking with -znow on "
"non-x86 architectures)"),
cl::init(bolt::PLTCall::OT_NONE),
cl::values(clEnumValN(bolt::PLTCall::OT_NONE, "none",
"do not optimize PLT calls"),
clEnumValN(bolt::PLTCall::OT_HOT, "hot",
"optimize executed (hot) PLT calls"),
clEnumValN(bolt::PLTCall::OT_ALL, "all",
"optimize all PLT calls")),
cl::ZeroOrMore, cl::cat(BoltOptCategory));
}
namespace llvm {
namespace bolt {
Error PLTCall::runOnFunctions(BinaryContext &BC) {
if (opts::PLT == OT_NONE)
return Error::success();
uint64_t NumCallsOptimized = 0;
for (auto &BFI : BC.getBinaryFunctions()) {
BinaryFunction &Function = BFI.second;
if (!shouldOptimize(Function))
continue;
if (opts::PLT == OT_HOT &&
Function.getExecutionCount() == BinaryFunction::COUNT_NO_PROFILE)
continue;
for (BinaryBasicBlock &BB : Function) {
if (opts::PLT == OT_HOT && !BB.getKnownExecutionCount())
continue;
for (auto II = BB.begin(); II != BB.end(); II++) {
if (!BC.MIB->isCall(*II))
continue;
const MCSymbol *CallSymbol = BC.MIB->getTargetSymbol(*II);
if (!CallSymbol)
continue;
const BinaryFunction *CalleeBF = BC.getFunctionForSymbol(CallSymbol);
if (!CalleeBF || !CalleeBF->isPLTFunction())
continue;
const InstructionListType NewCode = BC.MIB->createIndirectPLTCall(
std::move(*II), CalleeBF->getPLTSymbol(), BC.Ctx.get());
II = BB.replaceInstruction(II, NewCode);
assert(!NewCode.empty() && "PLT Call replacement must be non-empty");
std::advance(II, NewCode.size() - 1);
BC.MIB->addAnnotation(*II, "PLTCall", true);
++NumCallsOptimized;
}
}
}
if (NumCallsOptimized) {
// On X86-64, PLT optimization does not require -znow because the indirect
// call through GOT works correctly with lazy binding. At runtime, the
// resolver will populate the GOT entry on first call just like with a
// regular PLT call.
if (!BC.isX86())
BC.RequiresZNow = true;
BC.outs() << "BOLT-INFO: " << NumCallsOptimized
<< " PLT calls in the binary were optimized.\n";
}
return Error::success();
}
}
// namespace bolt
}
// namespace llvm
//===- bolt/Passes/PatchEntries.cpp - Pass for patching function entries --===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
//===--===//
//
// This file implements the PatchEntries class that is used for patching the
// original function entry points. This ensures that only the new/optimized code
// executes and that the old code is never used. This is necessary due to
// current BOLT limitations of not being able to duplicate all function's
// associated metadata (e.g., .eh_frame, exception ranges, debug info,
// jump-tables).
//
// NOTE: A successful run of 'scanExternalRefs' can relax this requirement as
// it also ensures that old code is never executed.
//
//===--===//
#include "bolt/Passes/PatchEntries.h"
#include "bolt/Utils/CommandLineOpts.h"
#include "bolt/Utils/NameResolver.h"
#include "llvm/ADT/STLExtras.h"
#include "llvm/Support/CommandLine.h"
namespace opts {
extern llvm::cl::OptionCategory BoltCategory;
extern llvm::cl::opt<unsigned> Verbosity;
}
// namespace opts
namespace llvm {
namespace bolt {
Error PatchEntries::runOnFunctions(BinaryContext &BC) {
if (!opts::ForcePatch) {
// Mark the binary for patching if we did not create external references
// for original code in any of functions we are not going to emit.
auto needsPatching = [&](const BinaryFunction &BF) {
// FIXME: keep compatibility for NFC testing.
if (BF.isFolded())
return false;
// Patching is always needed if explicitly requested.
if (BF.needsPatch())
return true;
return !BC.shouldEmit(BF) && !BF.hasExternalRefRelocations();
};
if (!llvm::any_of(llvm::make_second_range(BC.getBinaryFunctions()),
needsPatching))
return Error::success();
}
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: patching entries in original code\n";
// Calculate the size of the patch.
static size_t PatchSize = 0;
if (!PatchSize) {
InstructionListType Seq;
BC.MIB->createLongTailCall(Seq, BC.Ctx->createTempSymbol(), BC.Ctx.get());
PatchSize = BC.computeCodeSize(Seq.begin(), Seq.end());
}
static size_t FillerSize = 0;
if (BC.isX86() && FillerSize == 0) {
std::array<MCInst, 1> Seq;
BC.MIB->createBreakpoint(Seq[0]);
FillerSize = BC.computeCodeSize(Seq.begin(), Seq.end());
}
for (auto &BFI : BC.getBinaryFunctions()) {
BinaryFunction &Function = BFI.second;
// Patch original code only for functions that will be emitted.
if (!BC.shouldEmit(Function))
continue;
// Check if we can skip patching the function.
if (!opts::ForcePatch && !Function.hasEHRanges() &&
!Function.needsPatch() && Function.getSize() < PatchThreshold)
continue;
// List of patches for function entries. We either successfully patch
// all entries or, if we cannot patch one or more, do no patch any and
// mark the function as ignorable.
std::vector<Patch> PendingPatches;
uint64_t NextValidByte = 0;
// offset of the byte past the last patch
bool Success = Function.forEachEntryPoint([&](uint64_t Offset,
const MCSymbol *Symbol) {
if (Offset < NextValidByte) {
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: unable to patch entry point in " << Function
<< " at offset 0x" << Twine::utohexstr(Offset) << '\n';
return false;
}
NextValidByte = Offset + PatchSize;
if (NextValidByte > Function.getMaxSize()) {
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: function " << Function
<< " too small to patch its entry point\n";
return false;
}
const uint64_t PatchAddress = Function.getAddress() + Offset;
Patch P{Symbol, PatchAddress};
if (BC.isX86()) {
uint64_t OverwriteLength =
Function.getInstructionSequenceLength(Offset, PatchSize);
P.PaddingAfter = OverwriteLength - PatchSize;
assert(PendingPatches.empty() ||
(PendingPatches.back().Address + PatchSize +
PendingPatches.back().PaddingAfter <=
PatchAddress) &&
"Entry point cannot overlap with instruction stream of "
"previous entrypoint.");
}
PendingPatches.emplace_back(P);
return true;
});
if (!Success) {
// If the original function entries cannot be patched, then we cannot
// safely emit new function body.
BC.errs() << "BOLT-WARNING: failed to patch entries in " << Function
<< ". The function will not be optimized\n";
Function.setIgnored();
continue;
}
for (Patch &Patch : PendingPatches) {
// Add instruction patch to the binary.
InstructionListType Instructions;
BC.MIB->createLongTailCall(Instructions, Patch.Symbol, BC.Ctx.get());
if (BC.isX86()) {
assert(Patch.PaddingAfter % FillerSize == 0 &&
"Padding must be multiple of filler size.");
llvm::MCInst Inst;
BC.MIB->createBreakpoint(Inst);
Instructions.resize(
Instructions.size() + Patch.PaddingAfter / FillerSize, Inst);
}
BinaryFunction *PatchFunction = BC.createInstructionPatch(
Patch.Address, Instructions,
NameResolver::append(Patch.Symbol->getName(), ".org.0"));
if (BC.usesBTI())
BC.MIB->applyBTIFixupToSymbol(BC, Patch.Symbol,
*(Instructions.end() - 1));
// Verify the size requirements.
uint64_t HotSize, ColdSize;
std::tie(HotSize, ColdSize) = BC.calculateEmittedSize(*PatchFunction);
assert(!ColdSize && "unexpected cold code");
assert(HotSize <= PatchSize + Patch.PaddingAfter &&
"max patch size exceeded");
}
}
return Error::success();
}
}
// end namespace bolt
}
// end namespace llvm
//===- bolt/Passes/PettisAndHansen.cpp --===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
//===--===//
//
// The file implements Pettis and Hansen code-layout algorithm.
//
//===--===//
#include "bolt/Passes/HFSort.h"
#include "llvm/Support/Debug.h"
#include "llvm/Support/Format.h"
#include "llvm/Support/raw_ostream.h"
#include <set>
#include <unordered_map>
#define DEBUG_TYPE "hfsort"
namespace llvm {
namespace bolt {
using NodeId = CallGraph::NodeId;
using Arc = CallGraph::Arc;
using Node = CallGraph::Node;
namespace {
class ClusterArc {
public:
ClusterArc(Cluster *Ca, Cluster *Cb, double W = 0)
: C1(std::min(Ca, Cb)), C2(std::max(Ca, Cb)), Weight(W) {}
friend bool operator==(const ClusterArc &Lhs, const ClusterArc &Rhs) {
return Lhs.C1 == Rhs.C1 && Lhs.C2 == Rhs.C2;
}
Cluster *const C1;
Cluster *const C2;
mutable double Weight;
};
class ClusterArcHash {
public:
int64_t operator()(const ClusterArc &Arc) const {
std::hash<int64_t> Hasher;
return hashCombine(Hasher(int64_t(Arc.C1)), int64_t(Arc.C2));
}
};
using ClusterArcSet = std::unordered_set<ClusterArc, ClusterArcHash>;
void orderFuncs(const CallGraph &Cg, Cluster *C1, Cluster *C2) {
NodeId C1head = C1->targets().front();
NodeId C1tail = C1->targets().back();
NodeId C2head = C2->targets().front();
NodeId C2tail = C2->targets().back();
double C1headC2head = 0;
double C1headC2tail = 0;
double C1tailC2head = 0;
double C1tailC2tail = 0;
for (const Arc &Arc : Cg.arcs()) {
if ((Arc.src() == C1head && Arc.dst() == C2head) ||
(Arc.dst() == C1head && Arc.src() == C2head))
C1headC2head += Arc.weight();
else if ((Arc.src() == C1head && Arc.dst() == C2tail) ||
(Arc.dst() == C1head && Arc.src() == C2tail))
C1headC2tail += Arc.weight();
else if ((Arc.src() == C1tail && Arc.dst() == C2head) ||
(Arc.dst() == C1tail && Arc.src() == C2head))
C1tailC2head += Arc.weight();
else if ((Arc.src() == C1tail && Arc.dst() == C2tail) ||
(Arc.dst() == C1tail && Arc.src() == C2tail))
C1tailC2tail += Arc.weight();
}
const double Max = std::max(std::max(C1headC2head, C1headC2tail),
std::max(C1tailC2head, C1tailC2tail));
if (C1headC2head == Max) {
// flip C1
C1->reverseTargets();
} else if (C1headC2tail == Max) {
// flip C1 C2
C1->reverseTargets();
C2->reverseTargets();
} else if (C1tailC2tail == Max) {
// flip C2
C2->reverseTargets();
}
}
}
// namespace
std::vector<Cluster> pettisAndHansen(const CallGraph &Cg) {
// indexed by NodeId, keeps its current cluster
std::vector<Cluster *> FuncCluster(Cg.numNodes(), nullptr);
std::vector<Cluster> Clusters;
std::vector<NodeId> Funcs;
Clusters.reserve(Cg.numNodes());
for (NodeId F = 0; F < Cg.numNodes(); F++) {
if (Cg.samples(F) == 0)
continue;
Clusters.emplace_back(F, Cg.getNode(F));
FuncCluster[F] = &Clusters.back();
Funcs.push_back(F);
}
ClusterArcSet Carcs;
auto insertOrInc = [&](Cluster *C1, Cluster *C2, double Weight) {
auto Res = Carcs.emplace(C1, C2, Weight);
if (!Res.second)
Res.first->Weight += Weight;
};
// Create a std::vector of cluster arcs
for (const Arc &Arc : Cg.arcs()) {
if (Arc.weight() == 0)
continue;
Cluster *const S = FuncCluster[Arc.src()];
Cluster *const D = FuncCluster[Arc.dst()];
// ignore if s or d is nullptr
if (S == nullptr || D == nullptr)
continue;
// ignore self-edges
if (S == D)
continue;
insertOrInc(S, D, Arc.weight());
}
// Find an arc with max weight and merge its nodes
while (!Carcs.empty()) {
auto Maxpos = llvm::max_element(
Carcs, [&](const ClusterArc &Carc1, const ClusterArc &Carc2) {
return Carc1.Weight < Carc2.Weight;
});
ClusterArc Max = *Maxpos;
Carcs.erase(Maxpos);
Cluster *const C1 = Max.C1;
Cluster *const C2 = Max.C2;
if (C1->size() + C2->size() > MaxClusterSize)
continue;
if (C1->frozen() || C2->frozen())
continue;
// order functions and merge cluster
orderFuncs(Cg, C1, C2);
LLVM_DEBUG(dbgs() << format("merging %s -> %s: %.1f\n",
C2->toString().c_str(), C1->toString().c_str(),
Max.Weight));
// update carcs: merge C1arcs to C2arcs
std::unordered_map<ClusterArc, Cluster *, ClusterArcHash> C2arcs;
for (const ClusterArc &Carc : Carcs) {
if (Carc.C1 == C2)
C2arcs.emplace(Carc, Carc.C2);
if (Carc.C2 == C2)
C2arcs.emplace(Carc, Carc.C1);
}
for (auto It : C2arcs) {
Cluster *const C = It.second;
ClusterArc const C2arc = It.first;
insertOrInc(C, C1, C2arc.Weight);
Carcs.erase(C2arc);
}
// update FuncCluster
for (NodeId F : C2->targets())
FuncCluster[F] = C1;
C1->merge(*C2, Max.Weight);
C2->clear();
}
// Return the set of Clusters that are left, which are the ones that
// didn't get merged.
std::set<Cluster *> LiveClusters;
std::vector<Cluster> OutClusters;
for (NodeId Fid : Funcs)
LiveClusters.insert(FuncCluster[Fid]);
for (Cluster *C : LiveClusters)
OutClusters.push_back(std::move(*C));
llvm::sort(OutClusters, compareClustersDensity);
return OutClusters;
}
}
// namespace bolt
}
// namespace llvm
//===- bolt/Passes/PointerAuthCFIAnalyzer.cpp -===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
//===--===//
//
// This file implements the PointerAuthCFIAnalyzer class.
// Three CFIs have an influence on the RA State of an instruction:
// - NegateRAState flips the RA State,
// - RememberState pushes the RA State to a stack,
// - RestoreState pops the RA State from the stack.
// These are saved as MCAnnotations on instructions they refer to at CFI
// reading (in CFIReaderWriter::fillCFIInfoFor). In this pass, we can work out
// the RA State of each instruction, and save it as new MCAnnotations. The new
// annotations are Signing, Signed, Authenticating and Unsigned. After
// optimizations, .cfi_negate_ra_state CFIs are added to the places where the
// state changes in PointerAuthCFIFixup.
//
//===--===//
#include "bolt/Passes/PointerAuthCFIAnalyzer.h"
#include "bolt/Core/BinaryFunction.h"
#include "bolt/Core/ParallelUtilities.h"
#include <cstdlib>
#include <optional>
#include <stack>
using namespace llvm;
namespace opts {
extern llvm::cl::opt<unsigned> Verbosity;
}
// namespace opts
namespace llvm {
namespace bolt {
bool PointerAuthCFIAnalyzer::runOnFunction(BinaryFunction &BF) {
BinaryContext &BC = BF.getBinaryContext();
for (const BinaryBasicBlock &BB : BF) {
for (const MCInst &Inst : BB) {
if ((BC.MIB->isPSignOnLR(Inst) ||
(BC.MIB->isPAuthOnLR(Inst) && !BC.MIB->isPAuthAndRet(Inst))) &&
!BC.MIB->hasNegateRAState(Inst)) {
// Not all functions have .cfi_negate_ra_state in them. But if one does,
// we expect psign/pauth instructions to have the hasNegateRAState
// annotation.
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: inconsistent RAStates in function "
<< BF.getPrintName()
<< ": ptr sign/auth inst without .cfi_negate_ra_state\n";
std::lock_guard<std::mutex> Lock(IgnoreMutex);
BF.setIgnored();
return false;
}
}
}
bool RAState = BF.getInitialRAState();
std::stack<bool> RAStateStack;
RAStateStack.push(RAState);
for (BinaryBasicBlock &BB : BF) {
for (MCInst &Inst : BB) {
if (BC.MIB->isCFI(Inst))
continue;
if (BC.MIB->isPSignOnLR(Inst)) {
if (RAState) {
// RA signing instructions should only follow unsigned RA state.
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: inconsistent RAStates in function "
<< BF.getPrintName()
<< ": ptr signing inst encountered in Signed RA state\n";
std::lock_guard<std::mutex> Lock(IgnoreMutex);
BF.setIgnored();
return false;
}
} else if (BC.MIB->isPAuthOnLR(Inst)) {
if (!RAState) {
// RA authenticating instructions should only follow signed RA state.
if (opts::Verbosity >= 1)
BC.outs() << "BOLT-INFO: inconsistent RAStates in function "
<< BF.getPrintName()
<< ": ptr authenticating inst encountered in Unsigned RA "
"state\n";
std::lock_guard<std::mutex> Lock(IgnoreMutex);
BF.setIgnored();
return false;
}
}
BC.MIB->setRAState(Inst, RAState);
// Updating RAState. All updates are valid from the next instruction.
// Because the same instruction can have remember and restore, the order
// here is relevant. This is the reason to loop over Annotations instead
// of just checking each in a predefined order.
for (unsigned int Idx = 0; Idx < Inst.getNumOperands(); Idx++) {
std::optional<int64_t> Annotation =
BC.MIB->getAnnotationAtOpIndex(Inst, Idx);
if (!Annotation)
continue;
if (Annotation == MCPlus::MCAnnotation::kNegateState)
RAState = !RAState;
else if (Annotation == MCPlus::MCAnnotation::kRememberState)
RAStateStack.push(RAState);
else if (Annotation == MCPlus::MCAnnotation::kRestoreState) {
RAState = RAStateStack.top();
RAStateStack.pop();
}
}
}
}
return true;
}
Error PointerAuthCFIAnalyzer::runOnFunctions(BinaryContext &BC) {
std::atomic<uint64_t> FunctionsIgnored{0};
ParallelUtilities::WorkFuncTy WorkFun = [&](BinaryFunction &BF) {
if (!runOnFunction(BF)) {
FunctionsIgnored++;
}
};
ParallelUtilities::PredicateTy SkipPredicate = [&](const BinaryFunction &BF) {
// We can skip functions which did not include negate-ra-state CFIs. This
// includes code using pac-ret hardening as well, if the binary is
// compiled with `-fno-exceptions -fno-unwind-tables
// -fno-asynchronous-unwind-tables`
return !BF.containedNegateRAState() || BF.isIgnored();
};
int Total = llvm::count_if(BC.getBinaryFunctions(), [&](auto &P) {
return P.second.containedNegateRAState() && !P.second.isIgnored();
});
if (Total == 0)
return Error::success();
ParallelUtilities::runOnEachFunction(
BC, ParallelUtilities::SchedulingPolicy::SP_INST_LINEAR, WorkFun,
SkipPredicate, "PointerAuthCFIAnalyzer");
float IgnoredPercent = (100.0 * FunctionsIgnored) / Total;
BC.outs() << "BOLT-INFO: PointerAuthCFIAnalyzer ran on " << Total
<< " functions. Ignored " << FunctionsIgnored << " functions "
<< format("(%.2lf%%)", IgnoredPercent)
<< " because of CFI inconsistencies\n";
// Errors in the input are expected from two sources:
// - compilers emitting incorrect CFIs. This happens more frequently with
// older compiler versions, but it should not account for a large
// percentage.
// - input binary is using synchronous unwind tables. This means that after
// call sites, the unwind CFIs are dropped: the pass sees missing
// .cfi_negate_ra_state from autiasp instructions. If this is the case, a
// larger percentage of functions will be ignored.
//
// This is why the 10% threshold was chosen: we should not warn about
// synchronous unwind tables if only a few % are ignored.
if (IgnoredPercent >= 10.0)
BC.outs() << "BOLT-WARNING: PointerAuthCFIAnalyzer only supports "
"asynchronous unwind tables. For C compilers, see "
"-fasynchronous-unwind-tables.\n";
return Error::success();
}
}
// end namespace bolt
}
// end namespace llvm
//===- bolt/Passes/PointerAuthCFIFixup.cpp --===//
//
// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
// See https://llvm.org/LICENSE.txt for license information.
// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
//
//===--===//
//
// This file implements the PointerAuthCFIFixup class. It inserts
// OpNegateRAState CFIs to places where the state of two consecutive
// instructions are different.
//
//===--===//
#include "bolt/Passes/PointerAuthCFIFixup.h"
#include "bolt/Core/BinaryFunction.h"
#include "bolt/Core/ParallelUtilities.h"
#include <cstdlib>
using namespace llvm;
namespace llvm {
namespace bolt {
static bool PassFailed = false;
void PointerAuthCFIFixup::runOnFunction(BinaryFunction &BF) {
if (PassFailed)
return;
BinaryContext &BC = BF.getBinaryContext();
if (BF.getState() == BinaryFunction::State::Empty)
return;
if (BF.getState() != BinaryFunction::State::CFG &&
BF.getState() != BinaryFunction::State::CFG_Finalized) {
BC.outs() << "BOLT-INFO: no CFG for " << BF.getPrintName()
<< " in PointerAuthCFIFixup\n";
return;
}
inferUnknownStates(BF);
for (FunctionFragment &FF : BF.getLayout().fragments()) {
coverFunctionFragmentStart(BF, FF);
bool FirstIter = true;
bool PrevRAState = false;
// As this pass runs after function splitting, we should only check
// consecutive instructions inside FunctionFragments.
for (BinaryBasicBlock *BB : FF) {
for (auto It = BB->begin(); It != BB->end(); ++It) {
MCInst &Inst = *It;
if (BC.MIB->isCFI(Inst))
continue;
std::optional<bool> RAState = BC.MIB->getRAState(Inst);
if (!RAState.has_value()) {
BC.errs() << "BOLT-ERROR: unknown RAState after inferUnknownStates "
<< " in function " << BF.getPrintName() << "\n";
PassFailed = true;
return;
}
if (!FirstIter) {
// Consecutive instructions with different RAState means we need to
// add a OpNegateRAState.
if (*RAState != PrevRAState)
It = BF.addCFIInstruction(
BB, It, MCCFIInstruction::createNegateRAState(nullptr));
} else {
FirstIter = false;
}
PrevRAState = *RAState;
}
}
}
}
void PointerAuthCFIFixup::inferUnknownStates(BinaryFunction &BF) {
BinaryContext &BC = BF.getBinaryContext();
// Fill in missing RAStates in simple cases (inside BBs).
for (BinaryBasicBlock &BB : BF) {
fillUnknownStateInBB(BC, BB);
}
// BasicBlocks which are made entirely of "new instructions" (instructions
// without RAState annotation) are stubs, and do not have correct unwind info.
// We should iterate in layout order and fill them based on previous known
// RAState.
fillUnknownStubs(BF);
}
void PointerAuthCFIFixup::coverFunctionFragmentStart(BinaryFunction &BF,
FunctionFragment &FF) {
BinaryContext &BC = BF.getBinaryContext();
if (FF.empty())
return;
// Find the first BB in the FF which has Instructions.
// BOLT can generate empty BBs at function splitting which are only used as
// target labels. We should add the negate-ra-state CFI to the first
// non-empty BB.
auto *FirstNonEmpty =
std::find_if(FF.begin(), FF.end(), [](BinaryBasicBlock *BB) {
// getFirstNonPseudo returns BB.end() if it does not find any
// Instructions.
return BB->getFirstNonPseudo() != BB->end();
});
// If a function is already split in the input, the first FF can also start
// with Signed state. This covers that scenario as well.
auto II = (*FirstNonEmpty)->getFirstNonPseudo();
std::optional<bool> RAState = BC.MIB->getRAState(*II);
if (!RAState.has_value()) {
BC.errs() << "BOLT-ERROR: unknown RAState after inferUnknownStates "
<< " in function " << BF.getPrintName() << "\n";
PassFailed = true;
return;
}
if (*RAState)
BF.addCFIInstruction(*FirstNonEmpty, II,
MCCFIInstruction::createNegateRAState(nullptr));
}
std::optional<bool>
PointerAuthCFIFixup::getFirstKnownRAState(BinaryContext &BC,
BinaryBasicBlock &BB) {
for (const MCInst &Inst : BB) {
if (BC.MIB->isCFI(Inst))
continue;
std::optional<bool> RAState = BC.MIB->getRAState(Inst);
if (RAState.has_value())
return RAState;
}
return std::nullopt;
}
bool PointerAuthCFIFixup::isUnknownBlock(BinaryContext &BC,
BinaryBasicBlock &BB) {
std::optional<bool> FirstRAState = getFirstKnownRAState(BC, BB);
return !FirstRAState.has_value();
}
void PointerAuthCFIFixup::fillUnknownStateInBB(BinaryContext &BC,
BinaryBasicBlock &BB) {
auto First = BB.getFirstNonPseudo();
if (First == BB.end())
return;
// If the first instruction has unknown RAState, we should copy the first
// known RAState.
std::optional<bool> RAState = BC.MIB->getRAState(*First);
if (!RAState.has_value()) {
std::optional<bool> FirstRAState = getFirstKnownRAState(BC, BB);
if (!FirstRAState.has_value())
// We fill unknown BBs later.
return;
BC.MIB->setRAState(*First, *FirstRAState);
}
// At this point we know the RAState of the first instruction,
// so we can propagate the RAStates to all subsequent unknown instructions.
MCInst Prev = *First;
for (auto It = First + 1; It != BB.end(); ++It) {
MCInst &Inst = *It;
if (BC.MIB->isCFI(Inst))
continue;
// No need to check for nullopt: we only entered this loop after the first
// instruction had its RAState set, and RAState is always set for the
// previous instruction in the previous iteration of the loop.
std::optional<bool> PrevRAState = BC.MIB->getRAState(Prev);
std::optional<bool> RAState = BC.MIB->getRAState(Inst);
if (!RAState.has_value()) {
if (BC.MIB->isPSignOnLR(Prev))
PrevRAState = true;
else if (BC.MIB->isPAuthOnLR(Prev))
PrevRAState = false;
BC.MIB->setRAState(Inst, *PrevRAState);
}
Prev = Inst;
}
}
void PointerAuthCFIFixup::markUnknownBlock(BinaryContext &BC,
BinaryBasicBlock &BB, bool State) {
// If we call this when an Instruction has either kRASigned or kRAUnsigned
// annotation, setRAState would fail.
assert(isUnknownBlock(BC, BB) &&
"markUnknownBlock should only be called on unknown blocks");
for (MCInst &Inst : BB) {
if (BC.MIB->isCFI(Inst))
continue;
BC.MIB->setRAState(Inst, State);
}
}
void PointerAuthCFIFixup::fillUnknownStubs(BinaryFunction &BF) {
BinaryContext &BC = BF.getBinaryContext();
bool FirstIter = true;
MCInst PrevInst;
for (FunctionFragment &FF : BF.getLayout().fragments()) {
for (BinaryBasicBlock *BB : FF) {
if (FirstIter) {
FirstIter = false;
if (isUnknownBlock(BC, *BB))
// If the first BasicBlock is unknown, the function's entry RAState
// should be used.
markUnknownBlock(BC, *BB, BF.getInitialRAState());
} else if (isUnknownBlock(BC, *BB)) {
// As explained in issue #160989, the unwind info is incorrect for
// stubs. Indicating the correct RAState without the rest of the unwind
// info being correct is not useful. Instead, we copy the RAState from
// the previous instruction.
std::optional<bool> PrevRAState = BC.MIB->getRAState(PrevInst);
if (!PrevRAState.has_value()) {
// No non-cfi instruction encountered in the function yet.
// This means the RAState is the same as at the function entry.
markUnknownBlock(BC, *BB, BF.getInitialRAState());
continue;
}
if (BC.MIB->isPSignOnLR(PrevInst))
PrevRAState = true;
else if (BC.MIB->isPAuthOnLR(PrevInst))
PrevRAState = false;
markUnknownBlock(BC, *BB, *PrevRAState);
}
// This function iterates on BasicBlocks, so the PrevInst has to be
// updated to the last instruction of the current BasicBlock. If the
// BasicBlock is empty, or only has PseudoInstructions, PrevInst will not
// be updated.
auto Last = BB->getLastNonPseudo();
if (Last != BB->rend())
PrevInst = *Last;
}
}
}
Error PointerAuthCFIFixup::runOnFunctions(BinaryContext &BC) {
std::atomic<uint64_t> FunctionsModified{0};
ParallelUtilities::WorkFuncTy WorkFun = [&](BinaryFunction &BF) {
FunctionsModified++;
runOnFunction(BF);
};
ParallelUtilities::PredicateTy SkipPredicate = [&](const BinaryFunction &BF) {
// We can skip functions which did not include negate-ra-state CFIs. This
// includes code using pac-ret hardening as well, if the binary is
// compiled with `-fno-exceptions -fno-unwind-tables
// -fno-asynchronous-unwind-tables`
return !BF.containedNegateRAState() || BF.isIgnored();
};
ParallelUtilities::runOnEachFunction(
BC, ParallelUtilities::SchedulingPolicy::SP_INST_LINEAR, WorkFun,
SkipPredicate, "PointerAuthCFIFixup");
BC.outs() << "BOLT-INFO: rewritten pac-ret DWARF info in "
<< FunctionsModified << " out of " << BC.getBinaryFunctions().size()
<< " functions "
<< format("(%.2lf%%).\n", (100.0 * FunctionsModified) /
BC.getBinaryFunctions().size());
if (PassFailed)
return createFatalBOLTError("");
return Error::success();
}
}
// end namespace bolt
}
// end namespace llvm
